import {
	Component,
	ElementRef,
	forwardRef,
	ChangeDetectorRef,
	Input
} from '@angular/core';
import { NG_VALUE_ACCESSOR } from '@angular/forms';

import { PaginationComponent as NgxPaginationComponent } from 'ngx-bootstrap/pagination';
import { PaginationConfig } from 'ngx-bootstrap/pagination';
import { MessageService } from 'espd-common/i18n';


export const PAGINATION_CONTROL_VALUE_ACCESSOR: any = {
	provide: NG_VALUE_ACCESSOR,
	useExisting: forwardRef(() => PaginationComponent),
	multi: true
};

@Component({
    selector: 'espd-pagination',
    templateUrl: './pagination.component.html',
    styleUrls: ['pagination.component.scss'],
    providers: [PAGINATION_CONTROL_VALUE_ACCESSOR],
    standalone: false
})
export class PaginationComponent extends NgxPaginationComponent {

	@Input()
	public small: boolean = false;

	constructor(
		elementRef2: ElementRef,
		paginationConfig: PaginationConfig,
		changeDetection1: ChangeDetectorRef,
		public messageService: MessageService
	) {
		super(elementRef2, paginationConfig, changeDetection1);

		// Restore ability to use PaginationConfig. This was broken in ngx-bootstrap v7 and continues to be broken in v8
		this.align = <any>undefined;
		this.boundaryLinks = <any>undefined;
		this.directionLinks = <any>undefined;
		this.rotate = <any>undefined;
		this.pageBtnClass = <any>undefined;
		this.disabled = <any>undefined;
	}

	// eslint-disable-next-line id-blacklist
	public getAriaLabel(pg: { number: number; text: string; active: boolean }): string {
		if (pg.active) {
			return this.messageService.get('common.pagination.currentPage', pg.text);
		}
		if (pg.number === 1) {
			return this.messageService.get('common.pagination.first');
		}
		if (pg.number === this.totalPages) {
			return this.messageService.get('common.pagination.last', this.totalPages.toString());
		}
		return this.messageService.get('common.pagination.page', pg.text);
	}
}